{
  "name": "set_station_entry_value",
  "confidence": "medium",
  "docstring": "When an indexed station/table entry is valid, this stores the supplied value into the entry if its update-enable byte is set and then marks the entry dirty; it returns the input value unchanged.",
  "subsystem": "mac",
  "var_renames": {
    "result": "value",
    "a2": "index",
    "v2": "table_base",
    "v3": "entry"
  },
  "struct_hints": [
    {
      "offset": 24,
      "meaning": "entry valid/state word; if zero the update is skipped"
    },
    {
      "offset": 36,
      "meaning": "32-bit value stored when the entry allows updates"
    },
    {
      "offset": 45,
      "meaning": "dirty/update/active mark set to 1 when the entry is valid"
    },
    {
      "offset": 46,
      "meaning": "update-enable or auxiliary validity flag checked before writing offset 36"
    }
  ]
}
